query:
-- Get Freaky Friday project ID
SET @freaky_id = (SELECT id FROM projects WHERE title = 'Freaky Friday' LIMIT 1);

-- Add tags for Freaky Friday
INSERT INTO projectTags (projectId, tagId)
SELECT @freaky_id, id FROM tags WHERE name IN ('Musical Theatre', '2024', 'Summer Stock', 'Family Musical', 'Body Swap', 'Contemporary')
ON DUPLICATE KEY UPDATE projectId = projectId;

